              },
              "type": "array"
            }
          }
        },
        "fields": {
          "type": "array",
          "description": "Optional. Describes the nested schema fields if the type property is set to RECORD.",
          "items": {
            "$ref": "TableFieldSchema"
          }
        }
      },
      "type": "object",
      "description": "A field in TableSchema",
      "id": "TableFieldSchema"
