              "DAILY",
              "WEEKLY",
              "MONTHLY",
              "QUARTERLY",
              "YEARLY",
              "HOURLY"
            ],
            "type": "string"
          },
          "type": "array"
        },
        "arimaModelInfo": {
          "description": "This message is repeated because there are multiple arima models fitted in auto-arima. For non-auto-arima model, its size is one.",
          "items": {
            "$ref": "ArimaModelInfo"
          },
          "type": "array"
        }
