        "functionStats": {
          "description": "Function level stats for GenAI Functions. For more information, see [Generative AI overview](https://docs.cloud.google.com/bigquery/docs/generative-ai-overview).",
          "type": "array",
          "items": {
            "$ref": "GenAiFunctionStats"
          }
        }
      },
      "id": "GenAiStats",
      "type": "object",
      "description": "GenAi stats for the query job."
    }
